operation! {
    BitcastOp {
verify_hook: crate::builtin::bitcast_verify_impl,

        name: "bitcast",
        dialect: "builtin",
        scheme: "(_) -> _",
        verifier: "true",
        operands: O { input },
        results: R { result },
        sem: "(set result (bitcast input))",
        interfaces: [crate::Speculatable],
    }
}

pub(crate) fn bitcast_verify_impl(
    operation: &tir::OpHandle,
    context: &Context,
) -> Result<(), Error> {
    // An index is a scalar too, but only a data layout says how wide.
    let layout = crate::DataLayout::for_op(context, operation.id);
    let width = |value| {
        let ty = context.get_value(value).ty();
        crate::builtin::IntegerType::view(context, ty)
            .map(|int| int.width())
            .or_else(|| {
                crate::builtin::FloatType::view(context, ty)
                    .map(|float| u64::from(float.bit_width()))
            })
            .or_else(|| {
                crate::builtin::IndexType::view(context, ty)
                    .and_then(|_| layout.as_ref()?.index_width().map(u64::from))
            })
    };
    let input_width = width(operation.operands()[0]);
    let result_width = width(crate::builtin::bitcast_result(operation));
    if input_width.is_none() || result_width.is_none() {
        return Err(Error::VerificationError(
            "bitcast requires scalar integer, floating-point or index types".to_string(),
        ));
    }
    if input_width != result_width {
        return Err(Error::VerificationError(
            "bitcast source and result widths must match".to_string(),
        ));
    }
    Ok(())
}

use tir_symbolic::term::{no_carrier, valid};

use crate::parse::common::Cursor;
use crate::ty::{Ctor, Kind, Param, Terms, TypeArg, TypeCtor, TypeSpelling};
use crate::{Context, Error, TypeId};

use crate as tir;

static VARARGS: Ctor = Ctor::new(TypeCtor {
    dialect: "builtin",
    name: "varargs",
    params: &[],
    kind: Kind::Data,
    validate: valid,
    carrier: no_carrier,
});

/// The open tail of a function's parameter list, independent of its source language.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct VarArgsType;

impl VarArgsType {
    #[allow(clippy::new_ret_no_self)]
    pub fn new(context: &Context) -> TypeId {
        let terms = context.terms();
        terms
            .intern(VARARGS.id(terms), vec![])
            .expect("the varargs type")
    }

    pub fn view(terms: &impl AsRef<Terms>, ty: TypeId) -> Option<Self> {
        let terms = terms.as_ref();
        VARARGS.is(terms, ty).then_some(Self)
    }

    pub fn spelling(context: &Context) -> TypeSpelling {
        TypeSpelling {
            ctor: VARARGS.id(context),
            keys: &["varargs"],
            parse: |_, _, context| Ok(Self::new(context)),
            print: |_, _, fmt| fmt.write("varargs"),
            variadic_tail: true,
        }
    }
}

static FN: Ctor = Ctor::new(TypeCtor {
    dialect: "builtin",
    name: "fn",
    params: &[
        ("params", Param::List(Kind::Data)),
        ("ret", Param::One(Kind::Data)),
    ],
    kind: Kind::Data,
    validate: valid,
    carrier: no_carrier,
});

/// The type of a function value, written `!fn<(!i32, !i32) -> !i32>`.
///
/// A λ node produces one of these, and a call consumes it, so "which function
/// runs here" is a def-use question. A variadic signature ends in a
/// variadic-tail parameter type (see [`Context::is_variadic_tail`]) rather
/// than carrying a separate flag.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct FnType {
    params: Vec<TypeId>,
    ret: TypeId,
}

impl FnType {
    #[allow(clippy::new_ret_no_self)]
    pub fn new(context: &Context, params: &[TypeId], ret: TypeId) -> TypeId {
        let terms = context.terms();
        let params = params.iter().copied().map(TypeArg::Type).collect();
        terms
            .intern(
                FN.id(terms),
                vec![TypeArg::List(params), TypeArg::Type(ret)],
            )
            .expect("a signature of data types")
    }

    pub fn view(terms: &impl AsRef<Terms>, ty: TypeId) -> Option<Self> {
        let terms = terms.as_ref();
        FN.is(terms, ty).then(|| Self {
            params: super::tuple::type_list(terms.arg(ty, 0)),
            ret: terms.child(ty, 1).expect("a return type"),
        })
    }

    pub fn params(&self) -> Vec<TypeId> {
        self.params.clone()
    }

    pub fn ret(&self) -> TypeId {
        self.ret
    }

    /// The parameter and return types of `value`, when it is a function value.
    pub fn signature_of(context: &Context, value: crate::ValueId) -> Option<(Vec<TypeId>, TypeId)> {
        let signature = Self::view(context, context.get_value(value).ty())?;
        Some((signature.params, signature.ret))
    }

    pub fn spelling(context: &Context) -> TypeSpelling {
        TypeSpelling {
            ctor: FN.id(context),
            keys: &["fn"],
            parse: |_, parser, context| {
                if !parser.parse_token("<") {
                    return Err((parser.span(), Error::ExpectedToken("<")));
                }
                let params = parser
                    .parse_delimited("(", ")", |parser| {
                        parser
                            .parse_type(context)?
                            .ok_or_else(|| (parser.span(), Error::ExpectedType))
                    })?
                    .ok_or_else(|| (parser.span(), Error::ExpectedToken("(")))?;
                if !parser.parse_token("->") {
                    return Err((parser.span(), Error::ExpectedToken("->")));
                }
                let ret = parser
                    .parse_type(context)?
                    .ok_or_else(|| (parser.span(), Error::ExpectedType))?;
                if !parser.parse_token(">") {
                    return Err((parser.span(), Error::ExpectedToken(">")));
                }
                Ok(Self::new(context, &params, ret))
            },
            print: |spellings, ty, fmt| {
                let signature = Self::view(spellings, ty).expect("a function type");
                fmt.write("fn<(")?;
                for (index, param) in signature.params().into_iter().enumerate() {
                    if index > 0 {
                        fmt.write(", ")?;
                    }
                    spellings.print(param, fmt)?;
                }
                fmt.write(") -> ")?;
                spellings.print(signature.ret(), fmt)?;
                fmt.write(">")
            },
            variadic_tail: false,
        }
    }
}

// Takes a function's address as data, for a language that stores function
// pointers in memory. `!fn` values never live in memory themselves.
tir::operation! {
    FnToPtrOp {
        name: "fn_to_ptr",
        dialect: "builtin",
        scheme: "(fn<_, _>) -> ptr.p<_>",
        operands: O { callee },
        results: R { result },
        interfaces: [crate::Pure, crate::Speculatable],
    }
}

// Recovers a callable function value from an address, asserting the signature
// the call site expects. The inverse of `fn_to_ptr`.
tir::operation! {
    PtrToFnOp {
        name: "ptr_to_fn",
        dialect: "builtin",
        scheme: "(ptr.p<_>) -> fn<_, _>",
        operands: O { address },
        results: R { result },
        interfaces: [crate::Pure, crate::Speculatable],
    }
}

use crate::attributes::AttributeValue;
use crate::symbol_table::visibility_of;
use crate::{Context, Error, Global, IRFormatter, Symbol, TypeId, Visibility, operation};

use crate as tir;

/// A truncated address difference patched into a global after data layout.
pub struct SymbolDifference {
    pub offset: u64,
    pub symbol: String,
    pub base: String,
    pub width: u64,
}

// A δ node: a global data object, producing the address of its storage.
//
// A definition carries an alignment and either an initializer (`bytes`, plus the
// `relocations` patched into it) or a zero-filled `size`. A declaration of an
// object another module defines carries `external` and neither.
operation! {
    GlobalOp {
verify_hook: crate::builtin::global_verify_impl,
interface_callbacks: [(crate::Global, &crate::builtin::__TIR_IFACE_GlobalOp_Global), (crate::Symbol, &crate::builtin::__TIR_IFACE_GlobalOp_Symbol)],
print_hook: crate::builtin::global_custom_print,
parse_hook: |parser, context, _definition| crate::builtin::global_custom_parse(parser, context),

        name: "global",
        dialect: "builtin",
        scheme: "() -> ptr.p<_>",
        format: "custom",
        verifier: "true",
        interfaces: [Symbol, Global],
        attributes: A {
            sym_name: "Str",
        },
        results: R { result },
    }
}

pub(crate) fn global_global_address(operation: &tir::OpHandle) -> crate::ValueId {
    crate::builtin::global_result(operation)
}

pub(crate) fn global_global_initializer(operation: &tir::OpHandle) -> Option<Vec<u8>> {
    crate::builtin::global_bytes_attr(operation)
        .or_else(|| crate::builtin::global_size(operation).map(|size| vec![0; size as usize]))
}

#[allow(non_upper_case_globals)]
pub(crate) static __TIR_IFACE_GlobalOp_Global: crate::GlobalCallbacks = crate::GlobalCallbacks {
    address: crate::builtin::global_global_address,
    initializer: crate::builtin::global_global_initializer,
};

pub(crate) fn global_symbol_symbol_name(operation: &tir::OpHandle) -> String {
    crate::builtin::global_sym_name(operation)
}

pub(crate) fn global_symbol_symbol_signature(__operation: &tir::OpHandle) -> Option<Vec<TypeId>> {
    None
}

pub(crate) fn global_symbol_symbol_result_type(__operation: &tir::OpHandle) -> Option<TypeId> {
    None
}

pub(crate) fn global_symbol_symbol_visibility(operation: &tir::OpHandle) -> Visibility {
    visibility_of(operation)
}

pub(crate) fn global_symbol_is_definition(operation: &tir::OpHandle) -> bool {
    !crate::builtin::global_is_external(operation)
}

#[allow(non_upper_case_globals)]
pub(crate) static __TIR_IFACE_GlobalOp_Symbol: crate::SymbolCallbacks = crate::SymbolCallbacks {
    symbol_name: crate::builtin::global_symbol_symbol_name,
    symbol_signature: crate::builtin::global_symbol_symbol_signature,
    symbol_result_type: crate::builtin::global_symbol_symbol_result_type,
    symbol_visibility: crate::builtin::global_symbol_symbol_visibility,
    is_definition: crate::builtin::global_symbol_is_definition,
};

pub(crate) fn global_verify_impl(
    operation: &tir::OpHandle,
    _context: &Context,
) -> Result<(), Error> {
    crate::builtin::global_symbol_differences(operation)?;
    let name = crate::builtin::global_sym_name(operation);
    let defines = crate::builtin::global_bytes_attr(operation).is_some() as u8
        + crate::builtin::global_size(operation).is_some() as u8;
    if crate::builtin::global_is_external(operation) {
        if defines > 0 || crate::builtin::global_align(operation).is_some() {
            return Err(Error::VerificationError(format!(
                "external global '@{name}' declares storage it does not define"
            )));
        }
        return Ok(());
    }
    if defines != 1 {
        return Err(Error::VerificationError(format!(
            "global '@{name}' must carry either an initializer or a zero-filled size"
        )));
    }
    match crate::builtin::global_align(operation) {
        Some(align) if align.is_power_of_two() => Ok(()),
        _ => Err(Error::VerificationError(format!(
            "global '@{name}' must carry a power-of-two alignment"
        ))),
    }
}

/// Symbol differences whose operands must resolve in the same object section.
pub fn global_symbol_differences(
    operation: &tir::OpHandle,
) -> Result<Vec<SymbolDifference>, Error> {
    let invalid = || {
        Error::VerificationError(format!(
            "invalid symbol differences in global '@{}'",
            crate::builtin::global_sym_name(operation)
        ))
    };
    let Some(attribute) = operation.attr("symbol_differences") else {
        return Ok(Vec::new());
    };
    let AttributeValue::Array(entries) = attribute else {
        return Err(invalid());
    };
    let size = crate::builtin::global_bytes_attr(operation)
        .map(|bytes| bytes.len() as u64)
        .or_else(|| crate::builtin::global_size(operation))
        .ok_or_else(invalid)?;
    let number = |attribute: &AttributeValue| match attribute {
        AttributeValue::UInt(value) => Some(*value),
        AttributeValue::Int(value) => u64::try_from(*value).ok(),
        _ => None,
    };
    entries
        .iter()
        .map(|entry| {
            let AttributeValue::Dict(fields) = entry else {
                return Err(invalid());
            };
            let (
                Some(offset),
                Some(AttributeValue::Str(symbol)),
                Some(AttributeValue::Str(base)),
                Some(width),
            ) = (
                fields.get("offset").and_then(number),
                fields.get("symbol"),
                fields.get("base"),
                fields.get("width").and_then(number),
            )
            else {
                return Err(invalid());
            };
            if !matches!(width, 1 | 2 | 4 | 8)
                || offset.checked_add(width).is_none_or(|end| end > size)
            {
                return Err(invalid());
            }
            Ok(SymbolDifference {
                offset,
                symbol: symbol.to_string(),
                base: base.to_string(),
                width,
            })
        })
        .collect()
}

/// The address of this object's storage.
pub fn global_address(operation: &tir::OpHandle) -> crate::ValueId {
    crate::builtin::global_result(operation)
}

/// Whether this only declares an object another module defines.
pub fn global_is_external(operation: &tir::OpHandle) -> bool {
    operation.attr("external") == Some(AttributeValue::Bool(true))
}

pub fn global_align(operation: &tir::OpHandle) -> Option<u64> {
    match operation.attr("align")? {
        AttributeValue::UInt(align) => Some(align),
        _ => None,
    }
}

/// The zero-filled size, for an object with no initializer.
pub fn global_size(operation: &tir::OpHandle) -> Option<u64> {
    match operation.attr("size")? {
        AttributeValue::UInt(size) => Some(size),
        _ => None,
    }
}

/// The initializer image, before relocations are patched in.
pub fn global_bytes_attr(operation: &tir::OpHandle) -> Option<Vec<u8>> {
    let AttributeValue::Array(bytes) = operation.attr("bytes")? else {
        return None;
    };
    bytes
        .iter()
        .map(|byte| match byte {
            AttributeValue::UInt(value) => u8::try_from(*value).ok(),
            AttributeValue::Int(value) => u8::try_from(*value).ok(),
            _ => None,
        })
        .collect()
}

/// The section the object belongs to, when it is not the default for its
/// initializer.
pub fn global_section(operation: &tir::OpHandle) -> Option<String> {
    match operation.attr("section")? {
        AttributeValue::Str(name) => Some(name.to_string()),
        _ => None,
    }
}

/// `(offset, symbol, addend, width)` for each address patched into `bytes`.
pub fn global_relocations(operation: &tir::OpHandle) -> Vec<(u64, String, i64, u64)> {
    let Some(AttributeValue::Array(relocations)) = operation.attr("relocations") else {
        return Vec::new();
    };
    relocations
        .iter()
        .map(|relocation| {
            let AttributeValue::Dict(fields) = relocation else {
                unreachable!("a global relocation is a dictionary")
            };
            let AttributeValue::UInt(offset) = fields.get("offset").unwrap() else {
                unreachable!("a global relocation has an offset")
            };
            let AttributeValue::Str(symbol) = fields.get("symbol").unwrap() else {
                unreachable!("a global relocation has a symbol")
            };
            let AttributeValue::Int(addend) = fields.get("addend").unwrap() else {
                unreachable!("a global relocation has an addend")
            };
            let AttributeValue::UInt(width) = fields.get("width").unwrap() else {
                unreachable!("a global relocation has a width")
            };
            (*offset, symbol.to_string(), *addend, *width)
        })
        .collect()
}

pub(crate) fn global_custom_print(
    operation: &tir::OpHandle,
    fmt: &mut IRFormatter,
) -> Result<(), std::fmt::Error> {
    let context = operation.context.clone();
    fmt.write(format!(
        "%{} = global",
        crate::builtin::global_address(operation).number()
    ))?;
    if crate::builtin::global_symbol_symbol_visibility(operation) == Visibility::Private {
        fmt.write(" private")?;
    }
    if crate::builtin::global_is_external(operation) {
        fmt.write(" external")?;
    }
    fmt.write(format!(" @{}", crate::builtin::global_sym_name(operation)))?;
    if let Some(size) = crate::builtin::global_size(operation) {
        fmt.write(format!(" size {size}"))?;
    }
    if let Some(align) = crate::builtin::global_align(operation) {
        fmt.write(format!(" align {align}"))?;
    }
    if let Some(section) = crate::builtin::global_section(operation) {
        fmt.write(format!(" section \"{section}\""))?;
    }
    if let Some(bytes) = operation.attr("bytes") {
        fmt.write(" bytes ")?;
        bytes.print(fmt, &context)?;
    }
    if let Some(relocations) = operation.attr("relocations") {
        fmt.write(" relocations ")?;
        relocations.print(fmt, &context)?;
    }
    if let Some(differences) = operation.attr("symbol_differences") {
        fmt.write(" symbol_differences ")?;
        differences.print(fmt, &context)?;
    }
    fmt.write("\n")
}

pub(crate) fn global_custom_parse(
    parser: &mut tir::parse::text::Parser,
    context: &Context,
) -> Result<tir::OpHandle, (tir::parse::Span, Error)> {
    use tir::parse::common::Cursor;

    let is_private = parser.parse_token("private");
    let is_external = parser.parse_token("external");
    let sym_name = parser
        .parse_symbol_name()
        .ok_or_else(|| (parser.span(), Error::ExpectedSymbolName))?
        .to_string();

    let mut parts = tir::NewOpParts::default();
    if is_private {
        parts.attributes.push(context.named_attribute(
            "sym_visibility",
            AttributeValue::Str("private".to_string().into()),
        ));
    }
    if is_external {
        parts
            .attributes
            .push(context.named_attribute("external", AttributeValue::Bool(true)));
    }
    if parser.parse_token("size") {
        parts
            .attributes
            .push(context.named_attribute("size", AttributeValue::UInt(parse_number(parser)?)));
    }
    if parser.parse_token("align") {
        parts
            .attributes
            .push(context.named_attribute("align", AttributeValue::UInt(parse_number(parser)?)));
    }
    if parser.parse_token("section") {
        let section = parser
            .parse_string()
            .ok_or_else(|| (parser.span(), Error::ExpectedToken("section name")))?
            .to_string();
        parts
            .attributes
            .push(context.named_attribute("section", AttributeValue::Str(section.into())));
    }
    for name in ["bytes", "relocations", "symbol_differences"] {
        if !parser.parse_token(name) {
            continue;
        }
        let value = parser
            .parse_attribute_value(context)?
            .ok_or_else(|| (parser.span(), Error::ExpectedToken("attribute value")))?;
        parts.attributes.push(context.named_attribute(name, value));
    }

    Ok(r#global(
        context,
        sym_name.as_str(),
        crate::ptr::PtrType::opaque(context),
        parts,
        tir::InsertionPoint::Root,
    ))
}

fn parse_number(parser: &mut tir::parse::text::Parser) -> Result<u64, (tir::parse::Span, Error)> {
    use tir::parse::common::Cursor;
    parser
        .parse_number()
        .and_then(|value| u64::try_from(value).ok())
        .ok_or_else(|| (parser.span(), Error::ExpectedToken("a non-negative number")))
}

/// A δ definition holding `bytes`, aligned to `align`.
pub fn global_bytes(
    context: &Context,
    name: &str,
    bytes: Vec<u8>,
    align: u64,
    mut parts: tir::NewOpParts,
    insertion: tir::InsertionPoint,
) -> crate::OpHandle {
    parts.attributes.insert(
        0,
        context.named_attribute(
            "bytes",
            AttributeValue::Array(
                bytes
                    .into_iter()
                    .map(|byte| AttributeValue::UInt(u64::from(byte)))
                    .collect::<Vec<_>>()
                    .into(),
            ),
        ),
    );
    parts.attributes.insert(
        1,
        context.named_attribute("align", AttributeValue::UInt(align)),
    );
    r#global(
        context,
        name,
        crate::ptr::PtrType::opaque(context),
        parts,
        insertion,
    )
}

/// A δ definition reserving `size` zero bytes, aligned to `align`.
pub fn global_zero(
    context: &Context,
    name: &str,
    size: u64,
    align: u64,
    mut parts: tir::NewOpParts,
    insertion: tir::InsertionPoint,
) -> crate::OpHandle {
    parts.attributes.insert(
        0,
        context.named_attribute("size", AttributeValue::UInt(size)),
    );
    parts.attributes.insert(
        1,
        context.named_attribute("align", AttributeValue::UInt(align)),
    );
    r#global(
        context,
        name,
        crate::ptr::PtrType::opaque(context),
        parts,
        insertion,
    )
}

/// A δ declaration of an object another module defines.
pub fn global_external(
    context: &Context,
    name: &str,
    mut parts: tir::NewOpParts,
    insertion: tir::InsertionPoint,
) -> crate::OpHandle {
    parts.attributes.insert(
        0,
        context.named_attribute("external", AttributeValue::Bool(true)),
    );
    r#global(
        context,
        name,
        crate::ptr::PtrType::opaque(context),
        parts,
        insertion,
    )
}

use tir_symbolic::term::ctor;

use crate::parse::common::Cursor;
use crate::ty::{Terms, TypeArg, TypeSpelling};
use crate::{Context, Error, TypeId, operation};

use crate as tir;

/// `builtin.tuple<[T]>`, written `!tuple<!a, !b>`.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct TupleType(Vec<TypeId>);

impl TupleType {
    #[allow(clippy::new_ret_no_self)]
    pub fn new(context: &Context, elements: Vec<TypeId>) -> TypeId {
        let elements = elements.into_iter().map(TypeArg::Type).collect();
        context
            .terms()
            .intern(ctor::TUPLE, vec![TypeArg::List(elements)])
            .expect("a tuple of data types")
    }

    pub fn view(terms: &impl AsRef<Terms>, ty: TypeId) -> Option<Self> {
        let terms = terms.as_ref();
        (terms.ctor(ty) == ctor::TUPLE).then(|| Self(type_list(terms.arg(ty, 0))))
    }

    pub fn elements(&self) -> Vec<TypeId> {
        self.0.clone()
    }

    pub fn spelling(_context: &Context) -> TypeSpelling {
        TypeSpelling {
            ctor: ctor::TUPLE,
            keys: &["tuple"],
            parse: |_, parser, context| {
                let elements = parser
                    .parse_delimited("<", ">", |parser| {
                        parser
                            .parse_type(context)?
                            .ok_or_else(|| (parser.span(), Error::ExpectedType))
                    })?
                    .ok_or_else(|| (parser.span(), Error::ExpectedToken("<")))?;
                Ok(Self::new(context, elements))
            },
            print: |spellings, ty, fmt| {
                fmt.write("tuple<")?;
                let tuple = Self::view(spellings, ty).expect("a tuple type");
                for (index, element) in tuple.0.into_iter().enumerate() {
                    if index > 0 {
                        fmt.write(", ")?;
                    }
                    spellings.print(element, fmt)?;
                }
                fmt.write(">")
            },
            variadic_tail: false,
        }
    }
}

pub(crate) fn type_list(arg: Option<TypeArg>) -> Vec<TypeId> {
    let Some(TypeArg::List(items)) = arg else {
        return Vec::new();
    };
    items
        .iter()
        .filter_map(|item| match item {
            TypeArg::Type(ty) => Some(*ty),
            _ => None,
        })
        .collect()
}

operation! {
    MakeTupleOp {
verify_hook: crate::builtin::make_tuple_verify_impl,
interface_callbacks: [(crate::interp::Interp, &crate::interp::__TIR_IFACE_MakeTupleOp_Interp)],

        name: "make_tuple",
        dialect: "builtin",
        scheme: "(_*) -> tuple<_>",
        verifier: "true",
        operands: O { elements },
        results: R { result },
        interfaces: [crate::interp::Interp, crate::Speculatable],
    }
}

pub(crate) fn make_tuple_verify_impl(
    operation: &tir::OpHandle,
    context: &Context,
) -> Result<(), Error> {
    let Some(tuple) = TupleType::view(
        context,
        context
            .get_value(crate::builtin::make_tuple_result(operation))
            .ty(),
    ) else {
        return Err(Error::VerificationError(
            "make_tuple result must have tuple type".to_string(),
        ));
    };
    let expected = tuple.elements();
    if expected.len() != operation.operands().len() {
        return Err(Error::VerificationError(format!(
            "make_tuple expected {} elements, got {}",
            expected.len(),
            operation.operands().len()
        )));
    }
    for (index, (&value, expected_type)) in operation.operands().iter().zip(expected).enumerate() {
        if context.get_value(value).ty() != expected_type {
            return Err(Error::VerificationError(format!(
                "make_tuple element {index} has the wrong type"
            )));
        }
    }
    Ok(())
}

operation! {
    TupleGetOp {
verify_hook: crate::builtin::tuple_get_verify_impl,
interface_callbacks: [(crate::interp::Interp, &crate::interp::__TIR_IFACE_TupleGetOp_Interp)],

        name: "tuple_get",
        dialect: "builtin",
        scheme: "(tuple<_>) -> _",
        verifier: "true",
        operands: O { tuple },
        attributes: A {
            index: "UInt",
        },
        results: R { result },
        interfaces: [crate::interp::Interp, crate::Speculatable],
    }
}

pub fn tuple_get_tuple(operation: &tir::OpHandle) -> crate::ValueId {
    operation.operands()[0]
}

pub(crate) fn tuple_get_verify_impl(
    operation: &tir::OpHandle,
    context: &Context,
) -> Result<(), Error> {
    let Some(tuple) = TupleType::view(
        context,
        context
            .get_value(crate::builtin::tuple_get_tuple(operation))
            .ty(),
    ) else {
        return Err(Error::VerificationError(
            "tuple_get operand must have tuple type".to_string(),
        ));
    };
    let elements = tuple.elements();
    let Some(&expected) = elements.get(crate::builtin::tuple_get_index(operation) as usize) else {
        return Err(Error::VerificationError(format!(
            "tuple_get index {} is out of bounds for {} elements",
            crate::builtin::tuple_get_index(operation),
            elements.len()
        )));
    };
    if context
        .get_value(crate::builtin::tuple_get_result(operation))
        .ty()
        != expected
    {
        return Err(Error::VerificationError(
            "tuple_get result has the wrong type".to_string(),
        ));
    }
    Ok(())
}

//! Nominal types. `type.def !Name = !body` names a type in a module, and
//! `!Name` is then the term `type.named<Name, []>`: its identity is the name,
//! never the body. The body is read only where a layout is computed.
//!
//! The constructors a body is built from, `!struct`, `!union` and `!variant`,
//! hold `(name, type)` fields. Their layouts are regions of their core
//! definitions (`dialects/layout/types.rs`, see [`crate::layout`]).

use std::collections::BTreeMap;

use tir_symbolic::term::{ctor, no_carrier, valid};

use crate::attributes::AttributeValue;
use crate::parse::common::Cursor;
use crate::ty::{Ctor, Kind, Param, Terms, TypeArg, TypeCtor, TypeSpelling};
use crate::{Context, Error, IRFormatter, Symbol, TypeId, Visibility, dialect, operation};

use crate as tir;

dialect! {
    TypeDialect {
        name: "type",
        operations: [DEF],
        types: [],
    }
}

static STRUCT: Ctor = Ctor::new(TypeCtor {
    dialect: "type",
    name: "struct",
    params: &[
        ("fields", Param::Fields),
        ("packed", Param::Opt(Kind::Bool)),
    ],
    kind: Kind::Data,
    validate: valid,
    carrier: no_carrier,
});

static UNION: Ctor = Ctor::new(TypeCtor {
    dialect: "type",
    name: "union",
    params: &[("fields", Param::Fields)],
    kind: Kind::Data,
    validate: valid,
    carrier: no_carrier,
});

static VARIANT: Ctor = Ctor::new(TypeCtor {
    dialect: "type",
    name: "variant",
    params: &[("fields", Param::Fields), ("tag", Param::Opt(Kind::Data))],
    kind: Kind::Data,
    validate: valid,
    carrier: no_carrier,
});

/// `!Name` or `!Name<args>`: the type a `type.def` of the enclosing module
/// declares.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct NamedType {
    name: String,
    args: Vec<TypeArg>,
}

impl NamedType {
    /// The ground type `!name`.
    #[allow(clippy::new_ret_no_self)]
    pub fn new(context: &Context, name: &str) -> TypeId {
        Self::get(context, name, vec![]).expect("a named type")
    }

    /// `!name<args>`.
    pub fn get(
        terms: &impl AsRef<Terms>,
        name: &str,
        args: Vec<TypeArg>,
    ) -> Result<TypeId, String> {
        let terms = terms.as_ref();
        let name = TypeArg::Sym(terms.name(name));
        terms.intern(ctor::NAMED, vec![name, TypeArg::List(args.into())])
    }

    pub fn view(terms: &impl AsRef<Terms>, ty: TypeId) -> Option<Self> {
        let terms = terms.as_ref();
        if terms.ctor(ty) != ctor::NAMED {
            return None;
        }
        let term = terms.term(ty);
        let [TypeArg::Sym(name), TypeArg::List(args)] = term.args() else {
            return None;
        };
        Some(Self {
            name: terms.name_text(*name),
            args: args.to_vec(),
        })
    }

    pub fn name(&self) -> &str {
        &self.name
    }

    pub fn args(&self) -> &[TypeArg] {
        &self.args
    }

    pub fn spelling(_context: &Context) -> TypeSpelling {
        TypeSpelling {
            ctor: ctor::NAMED,
            // The parser reads a name no spelling claims as a named type.
            keys: &[],
            parse: |_, parser, _| Err((parser.span(), Error::ExpectedType)),
            print: |spellings, ty, fmt| {
                let named = Self::view(spellings, ty).expect("a named type");
                fmt.write(&named.name)?;
                if named.args.is_empty() {
                    return Ok(());
                }
                fmt.write("<")?;
                for (index, arg) in named.args.iter().enumerate() {
                    if index > 0 {
                        fmt.write(", ")?;
                    }
                    spellings.print_arg(arg, fmt)?;
                }
                fmt.write(">")
            },
            variadic_tail: false,
        }
    }
}

/// Which aggregate constructor a term is.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum AggregateKind {
    Struct,
    Union,
    Variant,
}

impl AggregateKind {
    fn ctor(self) -> &'static Ctor {
        match self {
            Self::Struct => &STRUCT,
            Self::Union => &UNION,
            Self::Variant => &VARIANT,
        }
    }

    fn keys(self) -> &'static [&'static str] {
        match self {
            Self::Struct => &["struct"],
            Self::Union => &["union"],
            Self::Variant => &["variant"],
        }
    }
}

/// `!struct<{a: !i32, b: !f64}>`, `!union<{..}>` or `!variant<{..}>`, the
/// variant optionally with its tag type: `!variant<{..}, !i8>`, a struct
/// with every field at byte alignment `!struct<{..}, true>`. A field's type
/// is a bound variable inside a generic definition. An argument equal to the
/// default the core type definitions give it is left out of the term.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct AggregateType {
    kind: AggregateKind,
    fields: Vec<(String, TypeArg)>,
}

impl AggregateType {
    pub fn get(
        terms: &impl AsRef<Terms>,
        kind: AggregateKind,
        fields: &[(&str, TypeArg)],
    ) -> Result<TypeId, String> {
        let terms = terms.as_ref();
        let fields = fields
            .iter()
            .map(|(name, ty)| TypeArg::List(Box::new([TypeArg::Sym(terms.name(name)), ty.clone()])))
            .collect();
        terms.intern(kind.ctor().id(terms), vec![TypeArg::List(fields)])
    }

    pub fn view(terms: &impl AsRef<Terms>, ty: TypeId) -> Option<Self> {
        let terms = terms.as_ref();
        let kind = [
            AggregateKind::Struct,
            AggregateKind::Union,
            AggregateKind::Variant,
        ]
        .into_iter()
        .find(|kind| kind.ctor().is(terms, ty))?;
        let term = terms.term(ty);
        let TypeArg::List(fields) = term.args().first()? else {
            return None;
        };
        let fields = fields
            .iter()
            .map(|field| match field {
                TypeArg::List(pair) => match &**pair {
                    [TypeArg::Sym(name), ty] => Some((terms.name_text(*name), ty.clone())),
                    _ => None,
                },
                _ => None,
            })
            .collect::<Option<_>>()?;
        Some(Self { kind, fields })
    }

    /// The struct `ty` with every field at byte alignment.
    pub fn packed(terms: &impl AsRef<Terms>, ty: TypeId) -> Option<TypeId> {
        let terms = terms.as_ref();
        if !STRUCT.is(terms, ty) {
            return None;
        }
        let fields = terms.term(ty).args().first()?.clone();
        terms
            .intern(STRUCT.id(terms), vec![fields, TypeArg::Nat(1)])
            .ok()
    }

    pub fn kind(&self) -> AggregateKind {
        self.kind
    }

    pub fn fields(&self) -> &[(String, TypeArg)] {
        &self.fields
    }

    /// The position of the field called `name`.
    pub fn field_index(&self, name: &str) -> Option<usize> {
        self.fields.iter().position(|(field, _)| field == name)
    }

    pub fn spelling(context: &Context, kind: AggregateKind) -> TypeSpelling {
        TypeSpelling {
            ctor: kind.ctor().id(context),
            keys: kind.keys(),
            parse: |mnemonic, parser, context| {
                let kind = match mnemonic {
                    "struct" => AggregateKind::Struct,
                    "union" => AggregateKind::Union,
                    _ => AggregateKind::Variant,
                };
                if !parser.parse_token("<") {
                    return Err((parser.span(), Error::ExpectedToken("<")));
                }
                // A generic definition's parameter may stand for the whole list.
                let fields = match parser.parse_type_arg(context)? {
                    Some(fields @ TypeArg::Var(_)) => fields,
                    _ => TypeArg::List(
                        parser
                            .parse_delimited("{", "}", |parser| {
                                let name = parser
                                    .parse_ident()
                                    .or_else(|| parser.parse_string())
                                    .ok_or_else(|| {
                                    (parser.span(), Error::ExpectedToken("field name"))
                                })?;
                                let name = TypeArg::Sym(context.terms().name(name));
                                if !parser.parse_token(":") {
                                    return Err((parser.span(), Error::ExpectedToken(":")));
                                }
                                let ty = parser
                                    .parse_type_arg(context)?
                                    .ok_or_else(|| (parser.span(), Error::ExpectedType))?;
                                Ok(TypeArg::List(Box::new([name, ty])))
                            })?
                            .ok_or_else(|| (parser.span(), Error::ExpectedToken("{")))?
                            .into(),
                    ),
                };
                let mut args = vec![fields];
                if kind != AggregateKind::Union && parser.parse_token(",") {
                    let flag = [("false", 0), ("true", 1)]
                        .into_iter()
                        .find(|(word, _)| parser.parse_token(word));
                    let arg = match flag {
                        Some((_, bit)) => TypeArg::Nat(bit),
                        None => parser
                            .parse_type_arg(context)?
                            .ok_or_else(|| (parser.span(), Error::ExpectedType))?,
                    };
                    args.push(arg);
                }
                if !parser.parse_token(">") {
                    return Err((parser.span(), Error::ExpectedToken(">")));
                }
                context
                    .terms()
                    .intern(kind.ctor().id(context), args)
                    .map_err(|message| (parser.span(), Error::VerificationError(message)))
            },
            print: |spellings, ty, fmt| {
                let Some(aggregate) = Self::view(spellings, ty) else {
                    return spellings.print_generic(ty, fmt);
                };
                fmt.write(format!("{}<{{", aggregate.kind.keys()[0]))?;
                for (index, (name, field)) in aggregate.fields.iter().enumerate() {
                    if index > 0 {
                        fmt.write(", ")?;
                    }
                    // A name that is no identifier, as C's `_x`, is quoted.
                    match is_identifier(name) {
                        true => fmt.write(format!("{name}: "))?,
                        false => fmt.write(format!("\"{name}\": "))?,
                    }
                    spellings.print_arg(field, fmt)?;
                }
                fmt.write("}")?;
                for arg in &spellings.terms().term(ty).args()[1..] {
                    fmt.write(", ")?;
                    match (aggregate.kind, arg) {
                        (AggregateKind::Struct, TypeArg::Nat(bit)) => fmt.write(match bit {
                            0 => "false",
                            _ => "true",
                        })?,
                        _ => spellings.print_arg(arg, fmt)?,
                    }
                }
                fmt.write(">")
            },
            variadic_tail: false,
        }
    }
}

fn is_identifier(name: &str) -> bool {
    name.chars().next().is_some_and(char::is_alphabetic)
        && name.chars().all(|c| c.is_alphanumeric() || c == '_')
}

// Every type `ty` holds by value, `ty` first, until `visit` says stop: an
// aggregate's fields, a tuple's or a vector's elements, and the body `expand`
// gives a named type. A pointer holds its pointee by reference, so the walk
// does not enter it.
pub(crate) fn contained_by_value(
    terms: &Terms,
    ty: TypeId,
    expand: impl Fn(TypeId) -> Option<TypeId>,
    mut visit: impl FnMut(TypeId) -> bool,
) {
    let mut stack = vec![ty];
    let mut seen = std::collections::HashSet::new();
    while let Some(ty) = stack.pop() {
        if !seen.insert(ty) || !visit(ty) || crate::ptr::PtrType::view(terms, ty).is_some() {
            continue;
        }
        if terms.ctor(ty) == ctor::NAMED {
            stack.extend(expand(ty));
            continue;
        }
        let term = terms.term(ty);
        let mut args: Vec<&TypeArg> = term.args().iter().collect();
        while let Some(arg) = args.pop() {
            match arg {
                TypeArg::Type(child) => stack.push(*child),
                TypeArg::List(items) => args.extend(items.iter()),
                TypeArg::Lam(_, body) => args.push(body),
                _ => {}
            }
        }
    }
}

// A parameter default as the term argument it stands for.
pub(crate) fn type_arg_of(value: &AttributeValue) -> Option<TypeArg> {
    match value {
        AttributeValue::Type(ty) => Some(TypeArg::Type(*ty)),
        AttributeValue::Bool(flag) => Some(TypeArg::Nat(u64::from(*flag))),
        value => Some(TypeArg::Nat(u64::try_from(value.as_int()?).ok()?)),
    }
}

/// Replace each bound variable `i` of `arg` by `values[i]`.
pub fn substitute(
    terms: &impl AsRef<Terms>,
    arg: &TypeArg,
    values: &[TypeArg],
) -> Result<TypeArg, String> {
    let terms = terms.as_ref();
    Ok(match arg {
        TypeArg::Var(index) => values
            .get(*index as usize)
            .cloned()
            .ok_or_else(|| format!("type argument {index} is missing"))?,
        TypeArg::Type(id) => {
            let term = terms.term(*id);
            let args = term
                .args()
                .iter()
                .map(|arg| substitute(terms, arg, values))
                .collect::<Result<Vec<_>, _>>()?;
            if args == term.args() {
                return Ok(arg.clone());
            }
            TypeArg::Type(terms.intern(term.ctor(), args)?)
        }
        TypeArg::List(items) => TypeArg::List(
            items
                .iter()
                .map(|item| substitute(terms, item, values))
                .collect::<Result<_, _>>()?,
        ),
        other => other.clone(),
    })
}

// What a layout region takes for each kind of parameter: a field list as
// the field types, a type, a number, a flag.
const PARAM_KINDS: [&str; 4] = ["fields", "data", "nat", "bool"];

// `type.def !Name<params> layout {packed} = !body layout (%spec: ..) {..}`.
//
// A definition with no body is incomplete: a pointer can point at it, nothing
// can hold it. The core type definitions, named after the
// aggregate constructors, give their layout regions.
operation! {
    TypeDefOp {
verify_hook: crate::builtin::def_verify_impl,
interface_callbacks: [(crate::Symbol, &crate::builtin::__TIR_IFACE_TypeDefOp_Symbol)],
print_hook: crate::builtin::def_custom_print,
parse_hook: |parser, context, _definition| crate::builtin::def_custom_parse(parser, context),

        name: "def",
        dialect: "type",
        scheme: "() -> ()",
        format: "custom",
        verifier: "true",
        interfaces: [Symbol],
        attributes: A {
            sym_name: "Str",
            // [[name, kind]] or [[name, kind, default]]; absent when ground.
            params: "?Array",
            // `packed`, `align` (bits).
            layout: "?Dict",
            // Absent: an incomplete type, pointers only.
            body: "?Type",
        },
        regions: R {
            region: Region {
                kind: Blocks,
                variadic: true,
            }
        },
    }
}

/// A `type.def` of `name` with `body`, or an incomplete one.
pub fn type_def(
    context: &Context,
    name: &str,
    body: Option<TypeId>,
    mut parts: tir::NewOpParts,
    insertion: tir::InsertionPoint,
) -> crate::OpHandle {
    if let Some(body) = body {
        define(context, name, body);
        parts.attributes.insert(
            0,
            context.named_attribute("body", AttributeValue::Type(body)),
        );
    }
    r#def(context, name, vec![], parts, insertion)
}

pub(crate) fn define(context: &Context, name: &str, body: TypeId) {
    let terms = context.terms();
    terms.define(terms.name(name), terms.kind(body));
}

