    operation: &tir::OpHandle,
    fmt: &mut tir::IRFormatter,
) -> Result<(), std::fmt::Error> {
    let context = operation.context.clone();
    fmt.write(format!(
        "cfg.cond_br %{}, ",
        crate::cfg::cond_br_condition(operation).number()
