pub fn round_reference_region(operation: &tir::OpHandle) -> tir::RegionHandle {
    operation.context.get_region(
        *operation
            .regions()
            .first()
            .expect("fp.round owns its reference"),
    )
}

pub(crate) fn round_custom_print(
    operation: &tir::OpHandle,
    fmt: &mut tir::IRFormatter,
) -> Result<(), std::fmt::Error> {
    let context = operation.handle().context.clone();
    let ports: Vec<_> = crate::fp::round_reference_region(operation)
        .ports()
        .iter()
        .map(tir::Value::id)
        .collect();
    tir::region_format::print_result_prefix(fmt, operation)?;
    fmt.write("fp.round")?;
    binding::print_port_bindings(fmt, &ports, &operation.operands())?;
    fmt.write(" {contract = ")?;
    AttributeValue::EvaluationContract(crate::fp::round_contract(operation))
        .print(fmt, &context)?;
    fmt.write("} : ")?;
    print_types(
        fmt,
        &context,
        &operation
            .results()
            .iter()
            .map(|result| context.get_value(*result).ty())
            .collect::<Vec<_>>(),
    )?;
    tir::region_format::print_region(fmt, &context, &crate::fp::round_reference_region(operation))
}

pub(crate) fn round_custom_parse(
    parser: &mut tir::parse::text::Parser,
    context: &Context,
) -> Result<tir::OpHandle, (tir::parse::Span, Error)> {
    let bound = binding::parse_port_bindings(parser, context)?;
    binding::expect(parser, "{")?;
    binding::expect(parser, "contract")?;
    binding::expect(parser, "=")?;
    let attribute = parser
        .parse_attribute_value(context)?
        .ok_or_else(|| (parser.span(), Error::ExpectedToken("contract")))?;
    let contract = super::EvaluationContract::parse_attribute(&attribute)
        .map_err(|error| (parser.span(), error))?;
    binding::expect(parser, "}")?;
    binding::expect(parser, ":")?;
    let result_types = parse_types(parser, context)?;
    let reference = parser
        .parse_region_with_entry_args(context, bound.ports)?
        .id();
    Ok(r#round(
        context,
        bound.inits,
        tir::attributes::AttributeValue::EvaluationContract(
            context.intern_evaluation_contract(contract),
        ),
        result_types,
        Some(reference),
        Default::default(),
        tir::InsertionPoint::Root,
    ))
}

pub(crate) fn round_verify_impl(operation: &tir::OpHandle, context: &Context) -> Result<(), Error> {
    let ports = crate::fp::round_reference_region(operation).ports();
    let captures = operation.operands();
    let yielded = crate::fp::round_reference_region(operation).results();
    let results = operation.results();
    if ports.len() != captures.len() {
        return Err(invalid(
            "fp.round must bind every capture to one reference port",
        ));
    }
    if yielded.len() != results.len() {
        return Err(invalid(
            "fp.round reference yield count must match its result count",
        ));
    }
    for (index, (port, capture)) in ports.iter().zip(captures).enumerate() {
        if port.ty() != context.get_value(capture).ty() {
            return Err(invalid(&format!(
                "fp.round port {index} must have its capture's type"
            )));
        }
    }
    for (index, (yielded, result)) in yielded.iter().zip(results.iter()).enumerate() {
        if context.get_value(*yielded).ty() != context.get_value(*result).ty() {
            return Err(invalid(&format!(
                "fp.round yield {index} must have its result's type"
            )));
        }
    }
    let formats: Vec<_> = results
        .iter()
        .filter_map(|result| {
            let ty = context.get_value(*result).ty();
            (!context.is_state_type(ty)).then_some(ty)
        })
        .collect();
    if crate::fp::round_contract(operation).result_formats != formats {
        return Err(invalid(
            "fp.round result formats must match its numeric results",
        ));
    }
    if results.iter().any(|result| {
        let ty = context.get_value(*result).ty();
        !context.is_state_type(ty) && FloatType::view(context, ty).is_none()
    }) {
        return Err(invalid("fp.round numeric results must have floating types"));
    }
    verify_explicit_captures(context, crate::fp::round_reference_region(operation).id())?;
    verify_primitive_semantics(
        context,
        crate::fp::round_reference_region(operation).id(),
        crate::fp::round_contract(operation).arithmetic,
    )?;
    let expected = super::resource::effects_for(
        Some(crate::fp::round_contract(operation).arithmetic.rounding),
        crate::fp::round_contract(operation).arithmetic.exceptions,
    );
    verify_body_effects(
        context,
        crate::fp::round_reference_region(operation).id(),
        &expected,
    )?;
    for resource in [StateResource::Memory, StateResource::FpEnv] {
        let count = usize::from(expected.iter().any(|(candidate, _)| *candidate == resource));
        if context.states_of(operation.operands(), resource).len() != count
            || context.states_of(results.iter().copied(), resource).len() != count
        {
            return Err(invalid("fp.round state ports do not match its contract"));
        }
        if expected
            .iter()
            .any(|&(candidate, access)| candidate == resource && access == ResourceAccess::Change)
        {
            verify_changed_state_is_yielded(
                context,
                crate::fp::round_reference_region(operation).id(),
                &yielded,
                resource,
            )?;
        }
    }
    Ok(())
}

fn parse_types(
    parser: &mut tir::parse::text::Parser,
    context: &Context,
) -> Result<Vec<tir::TypeId>, (tir::parse::Span, Error)> {
    if parser.parse_token("(") {
        let mut types = Vec::new();
        loop {
            types.push(
                parser
                    .parse_type(context)?
                    .ok_or_else(|| (parser.span(), Error::ExpectedType))?,
            );
            if parser.parse_token(")") {
                break;
            }
            binding::expect(parser, ",")?;
        }
        Ok(types)
    } else {
        Ok(vec![
            parser
                .parse_type(context)?
                .ok_or_else(|| (parser.span(), Error::ExpectedType))?,
        ])
    }
}

fn print_types(
    fmt: &mut tir::IRFormatter,
    context: &Context,
    types: &[tir::TypeId],
) -> Result<(), std::fmt::Error> {
    if types.len() > 1 {
        fmt.write("(")?;
    }
    for (index, ty) in types.iter().enumerate() {
        if index > 0 {
            fmt.write(", ")?;
        }
        context.print_type(*ty, fmt)?;
    }
    if types.len() > 1 {
        fmt.write(")")?;
    }
    Ok(())
}

fn invalid(message: &str) -> Error {
    Error::VerificationError(message.into())
}

fn verify_explicit_captures(context: &Context, region: tir::RegionId) -> Result<(), Error> {
    let handle = context.get_region(region);
    let mut local: std::collections::HashSet<_> =
        handle.ports().iter().map(tir::Value::id).collect();
    collect_defined(context, region, &mut local);
    for op in handle.op_ids() {
        for value in crate::region::values_read(context, op) {
            if !local.contains(&value) {
                return Err(invalid(
                    "fp.round reference may read outer values only through explicit capture ports",
                ));
            }
        }
    }
    if handle.results().iter().any(|value| !local.contains(value)) {
        return Err(invalid(
            "fp.round reference may yield outer values only through explicit capture ports",
        ));
    }
    Ok(())
}

fn collect_defined(
    context: &Context,
    region: tir::RegionId,
    values: &mut std::collections::HashSet<ValueId>,
) {
    let handle = context.get_region(region);
    values.extend(handle.ports().iter().map(tir::Value::id));
    for op in handle.op_ids() {
        let op = context.get_op(op);
        values.extend(op.results());
        for nested in op.regions() {
            collect_defined(context, nested, values);
        }
    }
}

fn verify_primitive_semantics(
    context: &Context,
    region: tir::RegionId,
    expected: super::ArithmeticSemantics,
) -> Result<(), Error> {
    for op in context.get_region(region).op_ids() {
        let op = context.get_op(op);
        if op.is_operation(&ROUND) {
            continue;
        }
        if let Some(AttributeValue::FpSemantics(semantics)) = op.attr("semantics")
            && semantics
                .arithmetic()
                .is_ok_and(|actual| *actual != expected)
        {
            return Err(invalid(
                "fp.round primitive semantics must match its contract",
            ));
        }
        for nested in op.regions() {
            verify_primitive_semantics(context, nested, expected)?;
        }
    }
    Ok(())
}

fn verify_body_effects(
    context: &Context,
    region: tir::RegionId,
    allowed: &[(StateResource, ResourceAccess)],
) -> Result<(), Error> {
    for op in context.get_region(region).op_ids() {
        let op = context.get_op(op);
        if let Some(effects) = op.clone().as_interface::<dyn ResourceEffects>() {
            for effect in effects.resource_effects() {
                let admitted = allowed.iter().any(|(resource, access)| {
                    *resource == effect.resource
                        && (*access == ResourceAccess::Change
                            || effect.access == ResourceAccess::Read)
                });
                if !admitted {
                    return Err(invalid(
                        "fp.round reference has a state effect absent from its contract",
                    ));
                }
            }
        }
        for nested in op.regions() {
            verify_body_effects(context, nested, allowed)?;
        }
    }
    Ok(())
}

fn verify_changed_state_is_yielded(
    context: &Context,
    region: tir::RegionId,
    yielded: &[ValueId],
    resource: StateResource,
) -> Result<(), Error> {
    let mut predecessors = std::collections::HashMap::<ValueId, Vec<ValueId>>::new();
    let mut changed = std::collections::HashSet::new();
    collect_state_effects(context, region, resource, &mut predecessors, &mut changed);

    let mut reachable = context.states_of(yielded.iter().copied(), resource);
    let mut visited = std::collections::HashSet::new();
    while let Some(state) = reachable.pop() {
        if visited.insert(state)
            && let Some(previous) = predecessors.get(&state)
        {
            reachable.extend(previous);
        }
    }
    if !changed.is_subset(&visited) {
        return Err(invalid(
            "fp.round reference must yield the final state of its body effects",
        ));
    }
    Ok(())
}

fn collect_state_effects(
    context: &Context,
    region: tir::RegionId,
    resource: StateResource,
    predecessors: &mut std::collections::HashMap<ValueId, Vec<ValueId>>,
    changed: &mut std::collections::HashSet<ValueId>,
) {
    for op in context.get_region(region).op_ids() {
        let op = context.get_op(op);
        if let Some(effects) = op.clone().as_interface::<dyn ResourceEffects>() {
            for effect in effects
                .resource_effects()
                .into_iter()
                .filter(|effect| effect.resource == resource)
            {
                for produced in &effect.produced {
                    predecessors
                        .entry(*produced)
                        .or_default()
                        .extend(&effect.observed);
                }
                if effect.access == ResourceAccess::Change {
                    changed.extend(effect.produced);
                }
            }
        }
        for chain in binding::state_chains(context, &op) {
            if context.state_resource(context.get_value(chain.left).ty()) != Some(resource) {
                continue;
            }
            predecessors
                .entry(chain.left)
                .or_default()
                .extend(&chain.exits);
            for port in chain.ports {
                predecessors.entry(port).or_default().push(chain.entered);
            }
            if let Some(next) = chain.next {
                predecessors.entry(next).or_default().extend(&chain.exits);
            }
        }
        if op.is_operation(&ROUND) {
            continue;
        }
        for nested in op.regions() {
            collect_state_effects(context, nested, resource, predecessors, changed);
        }
    }
}

use crate::attributes::AttributeValue;
use crate::builtin::{FnType, StateResource, UnitType};
use crate::{
    Apply, Context, Error, ResourceAccess, ResourceEffect, ResourceEffects, ValueId, operation,
};

use crate as tir;

operation! {
    CallOp {
verify_hook: crate::func::call_verify_impl,
interface_callbacks: [(crate::ResourceEffects, &crate::func::__TIR_IFACE_CallOp_ResourceEffects), (crate::Apply, &crate::func::__TIR_IFACE_CallOp_Apply)],
print_hook: crate::func::call_custom_print,
parse_hook: |parser, context, _definition| crate::func::call_custom_parse(parser, context),

        name: "call",
        dialect: "func",
        scheme: "(fn<_, _>, _*) -> _",
        format: "custom",
        verifier: "true",
        operands: O { callee, args },
        results: R { result },
        state: "in_out",
        interfaces: [Apply, ResourceEffects],
    }
}

pub(crate) fn call_resourceeffects_resource_effects(
    operation: &tir::OpHandle,
) -> Vec<ResourceEffect> {
    crate::func::call_resources(operation)
        .unwrap_or_else(|_| vec![StateResource::Memory, StateResource::FpEnv])
        .into_iter()
        .map(|resource| ResourceEffect {
            resource,
            access: ResourceAccess::Change,
            observed: operation
                .context
                .states_of(operation.state_operands(), resource),
            produced: operation
                .context
                .states_of(operation.state_results(), resource),
        })
        .collect()
}

#[allow(non_upper_case_globals)]
pub(crate) static __TIR_IFACE_CallOp_ResourceEffects: crate::ResourceEffectsCallbacks =
    crate::ResourceEffectsCallbacks {
        resource_effects: crate::func::call_resourceeffects_resource_effects,
    };

pub(crate) fn call_apply_callee(operation: &tir::OpHandle) -> ValueId {
    crate::func::call_callee(operation)
}

pub(crate) fn call_apply_args(operation: &tir::OpHandle) -> std::ops::Range<usize> {
    1..operation.value_operands().len()
}

#[allow(non_upper_case_globals)]
pub(crate) static __TIR_IFACE_CallOp_Apply: crate::ApplyCallbacks = crate::ApplyCallbacks {
    callee: crate::func::call_apply_callee,
    args: crate::func::call_apply_args,
};

pub(crate) fn call_verify_impl(operation: &tir::OpHandle, context: &Context) -> Result<(), Error> {
    crate::func::call_resources(operation)?;
    let args = crate::func::call_args(operation);
    super::verify_argument_alignments(operation, args.len(), "call")?;
    verify_result_address(operation, context, &args)?;

    let Some((parameters, ret_type)) =
        FnType::signature_of(context, crate::func::call_callee(operation))
    else {
        return Err(Error::VerificationError(
            "call callee must be a function value".to_string(),
        ));
    };
    let arg_types: Vec<_> = args
        .iter()
        .map(|arg| context.get_value(*arg).ty())
        .collect();
    if !tir::symbol_table::signature_accepts(context, &parameters, &arg_types) {
        return Err(Error::VerificationError(format!(
            "call passes ({}), but the callee takes ({})",
            type_list(context, &arg_types),
            type_list(context, &parameters)
        )));
    }
    let result_type = context.get_value(crate::func::call_result(operation)).ty();
    if result_type != ret_type {
        return Err(Error::VerificationError(format!(
            "call produces {}, but the callee returns {}",
            context.type_to_string(result_type),
            context.type_to_string(ret_type)
        )));
    }
    Ok(())
}

/// Resources the callee may access. An omitted summary is conservative.
pub fn call_resources(operation: &tir::OpHandle) -> Result<Vec<StateResource>, Error> {
    let Some(value) = operation.attr("resources") else {
        return Ok(vec![StateResource::Memory, StateResource::FpEnv]);
    };
    let invalid = || {
        Error::VerificationError(
            "call resources must be a non-empty list of distinct resource names".into(),
        )
    };
    let AttributeValue::Array(values) = value else {
        return Err(invalid());
    };
    if values.is_empty() {
        return Err(invalid());
    }
    let mut resources = Vec::new();
    for value in values {
        let AttributeValue::Str(name) = value else {
            return Err(invalid());
        };
        let resource = [StateResource::Memory, StateResource::FpEnv]
            .into_iter()
            .find(|resource| resource.name() == name.as_ref())
            .ok_or_else(invalid)?;
        if resources.contains(&resource) {
            return Err(invalid());
        }
        resources.push(resource);
    }
    Ok(resources)
}

pub fn call_callee(operation: &tir::OpHandle) -> ValueId {
    operation.operands()[0]
}

pub fn call_args(operation: &tir::OpHandle) -> Vec<ValueId> {
    operation.value_operands()[1..].to_vec()
}

pub fn call_has_result_address(operation: &tir::OpHandle) -> bool {
    has_result_address(operation)
}

pub fn call_argument_alignments(operation: &tir::OpHandle) -> Vec<u64> {
    super::argument_alignments(operation)
}

/// The symbol this call was bound to for machine lowering, once the callee
/// has been resolved to a λ of the module.
pub fn call_callee_symbol(operation: &tir::OpHandle) -> Option<String> {
    match operation.attr("callee")? {
        AttributeValue::Str(name) => Some(name.to_string()),
        _ => None,
    }
}

pub(crate) fn call_custom_print(
    operation: &tir::OpHandle,
    fmt: &mut tir::IRFormatter,
) -> Result<(), std::fmt::Error> {
    let context = operation.context.clone();
    let ret_type = context.get_value(crate::func::call_result(operation)).ty();
    let is_unit = ret_type == UnitType::new(&context);

    // A unit result is not spelled, so the binding is written by hand:
    // the value, the states, and `=` only where something is bound.
    let published = operation.state_results();
    if !is_unit {
        fmt.write(format!("%{}", crate::func::call_result(operation).number()))?;
    }
    if !is_unit && !published.is_empty() {
        fmt.write(", ")?;
    }
    tir::region_format::print_value_list(fmt, &published)?;
    if !is_unit || !published.is_empty() {
        fmt.write(" = ")?;
    }
    fmt.write(format!(
        "func.call %{}",
        crate::func::call_callee(operation).number()
    ))?;

    let args = crate::func::call_args(operation);
    fmt.write("(")?;
    for (i, arg) in args.iter().enumerate() {
        if i > 0 {
            fmt.write(", ")?;
        }
        fmt.write(format!("%{}", arg.number()))?;
    }
    if !args.is_empty() {
        fmt.write(" : ")?;
        for (i, arg) in args.iter().enumerate() {
            if i > 0 {
                fmt.write(", ")?;
            }
            context.print_type(context.get_value(*arg).ty(), fmt)?;
        }
    }
    fmt.write(")")?;

    if !is_unit {
        fmt.write(" -> ")?;
        context.print_type(ret_type, fmt)?;
    }
    if crate::func::call_has_result_address(operation) {
        fmt.write(" result_address")?;
    }
    if let Some(symbol) = crate::func::call_callee_symbol(operation) {
        fmt.write(format!(" callee @{symbol}"))?;
    }
    super::print_keyed_list(
        fmt,
        "argument_alignments",
        &crate::func::call_argument_alignments(operation),
    )?;
    if operation.attr("resources").is_some() {
        let resources = crate::func::call_resources(operation).map_err(|_| std::fmt::Error)?;
        let names = resources
            .iter()
            .map(|resource| format!("\"{}\"", resource.name()))
            .collect::<Vec<_>>();
        fmt.write(format!(" resources [{}]", names.join(", ")))?;
    }
    tir::region_format::print_state_operands(fmt, operation)?;
    fmt.write("\n")
}

pub(crate) fn call_custom_parse(
    parser: &mut tir::parse::text::Parser,
    context: &Context,
) -> Result<tir::OpHandle, (tir::parse::Span, Error)> {
    use tir::parse::common::Cursor;
    let callee_ref = parser
        .parse_value_ref()
        .ok_or_else(|| (parser.span(), Error::ExpectedValueRef))?
        .to_string();
    let callee = parser.resolve_value(context, &callee_ref);
    let args = parse_arg_list(parser, context)?;
    let ret_type = parse_ret_type(parser, context)?;
    let result_address = parser.parse_token("result_address");
    let callee_symbol = parser
        .parse_token("callee")
        .then(|| {
            parser
                .parse_symbol_name()
                .map(str::to_string)
                .ok_or_else(|| (parser.span(), Error::ExpectedSymbolName))
        })
        .transpose()?;
    let argument_alignments =
        super::parse_keyed_array(parser, context, "argument_alignments", "alignment list")?;

    let resources = super::parse_keyed_array(parser, context, "resources", "resource list")?;
    let state = parser.parse_state_operands(context)?;
    let mut parts = tir::NewOpParts::default();
    if result_address {
        parts
            .attributes
            .push(context.named_attribute("result_address", AttributeValue::Bool(true)));
    }
    if let Some(symbol) = callee_symbol {
        parts
            .attributes
            .push(context.named_attribute("callee", AttributeValue::Str(symbol.into())));
    }
    if let Some(argument_alignments) = argument_alignments {
        parts
            .attributes
            .push(context.named_attribute("argument_alignments", argument_alignments));
    }
    if let Some(resources) = resources {
        parts
            .attributes
            .push(context.named_attribute("resources", resources));
    }
    Ok(r#call(
        context,
        callee,
        args,
        ret_type,
        state,
        vec![],
        parts,
        tir::InsertionPoint::Root,
    ))
}

fn type_list(context: &Context, types: &[tir::TypeId]) -> String {
    types
        .iter()
        .map(|ty| context.type_to_string(*ty))
        .collect::<Vec<_>>()
        .join(", ")
}

fn verify_result_address(
    op: &tir::OpHandle,
    context: &Context,
    args: &[ValueId],
) -> Result<(), Error> {
    if !has_result_address(op) {
        return Ok(());
    }
    let Some(destination) = args.first().copied() else {
        return Err(Error::VerificationError(
            "result-address call requires a destination argument".to_string(),
        ));
    };
    if crate::ptr::PtrType::view(context, context.get_value(destination).ty()).is_none() {
        return Err(Error::VerificationError(
            "result-address call destination must have pointer type".to_string(),
        ));
    }
    Ok(())
}

fn parse_arg_list(
    parser: &mut tir::parse::text::Parser,
    context: &Context,
) -> Result<Vec<ValueId>, (tir::parse::Span, Error)> {
    use tir::parse::common::Cursor;
    if !parser.parse_token("(") {
        return Err((parser.span(), Error::ExpectedToken("(")));
    }
    let mut args = vec![];
    if parser.parse_token(")") {
        return Ok(args);
    }
    loop {
        let arg_ref = parser
            .parse_value_ref()
            .ok_or_else(|| (parser.span(), Error::ExpectedValueRef))?
            .to_string();
        args.push(parser.resolve_value(context, &arg_ref));
        if !parser.parse_token(",") {
            break;
        }
    }
    if !parser.parse_token(":") {
        return Err((parser.span(), Error::ExpectedToken(":")));
    }
    loop {
        parser
            .parse_type(context)?
            .ok_or_else(|| (parser.span(), Error::ExpectedType))?;
        if !parser.parse_token(",") {
            break;
        }
    }
    if !parser.parse_token(")") {
        return Err((parser.span(), Error::ExpectedToken(")")));
    }
    Ok(args)
}

fn parse_ret_type(
    parser: &mut tir::parse::text::Parser,
    context: &Context,
) -> Result<tir::TypeId, (tir::parse::Span, Error)> {
    use tir::parse::common::Cursor;
    if parser.parse_token("->") {
        parser
            .parse_type(context)?
            .ok_or_else(|| (parser.span(), Error::ExpectedType))
    } else {
        Ok(UnitType::new(context))
    }
}

