    crate::interp::InterpCallbacks {
        evaluate: crate::layout::at_interp_evaluate,
    };

// A folded query as the constant its semantics is, so the op is a value the
// rewriters fold; `None`, and no semantics, where it does not fold.
fn constant_node(
    value: Option<crate::sem::Value>,
    g: &mut crate::sem::SemGraph,
) -> Option<crate::NodeId> {
    let crate::sem::Value::Int(value) = value? else {
        return None;
    };
    let node = g.add_node(crate::sem::SymKind::Constant);
    g.set_leaf_data(node, crate::sem::SymPayload::Int(value));
    Some(node)
}

pub(crate) fn sizeof_folded(
    operation: &tir::OpHandle,
    g: &mut crate::sem::SemGraph,
) -> Option<crate::NodeId> {
    constant_node(sizeof_constantfold_fold(operation, &[]), g)
}

pub(crate) fn alignof_folded(
    operation: &tir::OpHandle,
    g: &mut crate::sem::SemGraph,
) -> Option<crate::NodeId> {
    constant_node(alignof_constantfold_fold(operation, &[]), g)
}

pub(crate) fn offsetof_folded(
    operation: &tir::OpHandle,
    g: &mut crate::sem::SemGraph,
) -> Option<crate::NodeId> {
    constant_node(offsetof_constantfold_fold(operation, &[]), g)
}

/// `layout.sizeof {ty = ty} : !i<width>`.
pub fn size_of(
    context: &Context,
    ty: TypeId,
    width: u32,
    mut parts: tir::NewOpParts,
    insertion: tir::InsertionPoint,
) -> tir::OpHandle {
    parts
        .attributes
        .insert(0, context.named_attribute("ty", AttributeValue::Type(ty)));
    crate::layout::r#sizeof(
        context,
        vec![],
        crate::builtin::IntegerType::new(context, u64::from(width)),
        parts,
        insertion,
    )
}

/// `layout.offsetof {ty = ty, field = field} : !i<width>`.
pub fn offset_of(
    context: &Context,
    ty: TypeId,
    field: &str,
    width: u32,
    parts: tir::NewOpParts,
    insertion: tir::InsertionPoint,
) -> tir::OpHandle {
    crate::layout::r#offsetof(
        context,
        ty,
        field,
        crate::builtin::IntegerType::new(context, u64::from(width)),
        parts,
        insertion,
    )
}

impl From<LayoutSpec> for AttributeValue {
    fn from(spec: LayoutSpec) -> Self {
        AttributeValue::LayoutSpec(Arc::new(spec))
    }
}

//! The `ptr` dialect: pointers plus the loads and stores that read and write
//! through them. It is deliberately tiny — just enough to express the
//! memory-based (non-SSA) lowering a simple C frontend produces, where every
//! local lives in a stack slot. Pointer arithmetic is byte-based and loads/stores
//! carry no offset. Every integer added to or taken from a pointer is exactly as
//! wide as the pointer, the width the data layout gives `p`, so a constant added
