        interface_callbacks: [(tir::backend::MachineInstruction, &PCOPY_MACHINE_INSTRUCTION)],
        name: "pcopy",
        dialect: "asm",
        scheme: "(_*) -> _*",
        operands: O { sources },
        results: R { copies },
        interfaces: [tir::backend::MachineInstruction],
    }
}

